  $nihtjson${"slug": "nursing-informatics-healthcare-technology", "title": "Nursing Informatics / Healthcare Technology", "description": "This course develops nursing informatics practice across the DIKW framework, electronic health records, standardized terminologies, interoperability, clinical decision support, privacy and cybersecurity, telehealth, patient-facing technology, analytics, workflow and usability, public health surveillance, responsible AI, implementation, digital equity, and technology impact evaluation.", "topics": [{"id": "0364582f-6e59-4ba7-93ae-e68b03cb32a3", "type": "topic", "title": "Nursing Informatics Foundations and the DIKW Framework", "description": "Students learn how nursing informatics connects people, data, information, knowledge, wisdom, workflow, and patient outcomes.", "children": [{"id": "acb6903b-e104-4cb4-98df-38116e1b30e7", "type": "subtopic", "title": "Nursing informatics scope", "description": "The gist is understanding informatics as nursing knowledge work supported by systems.", "children": [{"id": "2f20450a-0e66-44a0-a7eb-4bb21e2146ee", "type": "concept", "title": "Data, information, knowledge, wisdom"}, {"id": "f40421e3-bac7-4842-a1e7-476abd59da36", "type": "concept", "title": "Nursing judgment and technology-enabled care"}, {"id": "697b9162-9dd7-44fa-9208-4fb32672fbdb", "type": "concept", "title": "Roles: bedside nurse, super user, informatics nurse, analyst, CNIO"}]}, {"id": "aa9a4d43-1755-49f3-bf1b-fd9d2099d128", "type": "subtopic", "title": "Sociotechnical systems", "description": "Healthcare technology works only when people, workflow, policy, and tools fit together.", "children": [{"id": "d167c254-e082-4090-a91f-eb415fb200f2", "type": "concept", "title": "People, process, technology, organization, and environment"}, {"id": "38a5c445-fb0d-485f-943c-993e2c69419e", "type": "concept", "title": "Unintended consequences"}, {"id": "d59444c4-44dd-44da-8133-8919592b19d9", "type": "concept", "title": "Safety, quality, and usability as design goals"}]}, {"id": "542ec025-c886-41fe-b08c-769862803bec", "type": "subtopic", "title": "AACN informatics competencies", "description": "Students connect course learning to professional nursing expectations.", "children": [{"id": "72ba971b-c56c-4811-975b-7a6cb65bca70", "type": "concept", "title": "Healthcare technologies"}, {"id": "a5ad3156-1e16-48cf-bca3-fb4267aa79aa", "type": "concept", "title": "Information and communication technologies"}, {"id": "6c8d6656-f1d9-4b57-aff0-2da4add81dd7", "type": "concept", "title": "Data-driven care and ethical practice"}]}]}, {"id": "f720730f-f429-4d92-bd6f-d19372c2bfc1", "type": "topic", "title": "Health Information Systems, EHRs, and Clinical Documentation", "description": "This topic develops fluent, safety-minded use of EHRs and documentation systems as clinical tools rather than passive charting software.", "children": [{"id": "859b2d85-9870-499b-84f5-6720ecaa8a9d", "type": "subtopic", "title": "EHR and EMR foundations", "description": "Students learn what clinical systems store, display, and coordinate.", "children": [{"id": "d0d44128-ed8e-4791-b0c8-d67a00fda2d3", "type": "concept", "title": "Orders, notes, medication administration, results, care plans"}, {"id": "936d1ab9-92f0-4f0f-a4b3-6c440b79a7bb", "type": "concept", "title": "Clinical documentation workflows"}, {"id": "5ed5cedb-e688-4f09-a696-4baa254068e1", "type": "concept", "title": "Chart review and longitudinal patient story"}]}, {"id": "771ea37a-3775-4718-9201-72d97aa31f47", "type": "subtopic", "title": "Clinical documentation quality", "description": "Documentation is clinical communication and legal evidence.", "children": [{"id": "c1a96c9e-41f8-4d55-b211-5795a932309d", "type": "concept", "title": "Accuracy, timeliness, completeness, and relevance"}, {"id": "c3163280-3504-4b6e-8337-cef019237352", "type": "concept", "title": "Problem lists, allergies, medication reconciliation, and handoff notes"}, {"id": "a9f7c090-b89a-47a9-b411-da21cb24e465", "type": "concept", "title": "Copy-forward risks and note bloat"}]}, {"id": "086edf82-955c-4c24-a364-210cb60f779f", "type": "subtopic", "title": "Specialized systems", "description": "Nurses work across many connected platforms.", "children": [{"id": "46bb81cc-91ac-4174-91e9-e52bf0fc87cc", "type": "concept", "title": "CPOE, eMAR, BCMA, LIS, PACS, pharmacy, bed management"}, {"id": "695fabff-f0ba-4fba-aa09-56469951b051", "type": "concept", "title": "Patient portals and scheduling systems"}, {"id": "bc4339c0-27fd-4d43-a3fc-28dca2ee8028", "type": "concept", "title": "Downtime procedures and contingency charting"}]}]}, {"id": "e4b76e7a-8f58-440f-8a89-89491455a52d", "type": "topic", "title": "Standardized Terminologies, Nursing-Sensitive Data, and Data Quality", "description": "Students learn why structured language and high-quality data matter for communication, reimbursement, analytics, quality, and nursing visibility.", "children": [{"id": "8722d243-ec29-4580-ae45-2f00c97897c8", "type": "subtopic", "title": "Nursing terminologies", "description": "Standardized language helps nursing care become visible and computable.", "children": [{"id": "e3715ea2-68a7-4e45-a9b5-fae10ded2bb6", "type": "concept", "title": "NANDA-I diagnoses"}, {"id": "68b87751-db6a-4492-a528-75a40956a926", "type": "concept", "title": "NIC interventions"}, {"id": "7567f9d5-6884-4e49-bfa8-de4eefba31a2", "type": "concept", "title": "NOC outcomes"}, {"id": "02221e3c-b981-4be4-896e-afef4b1f13f9", "type": "concept", "title": "SNOMED CT and LOINC awareness"}]}, {"id": "17dd499f-b9d3-4e17-94e8-68979cc885c7", "type": "subtopic", "title": "Nursing-sensitive data", "description": "Students learn which data reveal nursing contribution to outcomes.", "children": [{"id": "f0d62587-598a-4fe5-8842-810136ada74f", "type": "concept", "title": "Falls, pressure injuries, CAUTI, CLABSI, pain, mobility, education"}, {"id": "fb745dfe-760b-48b9-a754-bf5f10041352", "type": "concept", "title": "Care plans and outcome measures"}, {