update public.learning_paths
set
  title = 'Nursing Informatics / Healthcare Technology',
  goal = 'Nursing Informatics / Healthcare Technology',
  summary = 'This course develops nursing informatics practice across the DIKW framework, electronic health records, standardized terminologies, interoperability, clinical decision support, privacy and cybersecurity, telehealth, patient-facing technology, analytics, workflow and usability, public health surveillance, responsible AI, implementation, digital equity, and technology impact evaluation.',
  data = $nihtjson${"slug": "nursing-informatics-healthcare-technology", "title": "Nursing Informatics / Healthcare Technology", "description": "This course develops nursing informatics practice across the DIKW framework, electronic health records, standardized terminologies, interoperability, clinical decision support, privacy and cybersecurity, telehealth, patient-facing technology, analytics, workflow and usability, public health surveillance, responsible AI, implementation, digital equity, and technology impact evaluation.", "topics": [{"id": "0364582f-6e59-4ba7-93ae-e68b03cb32a3", "type": "topic", "title": "Nursing Informatics Foundations and the DIKW Framework", "description": "Students learn how nursing informatics connects people, data, information, knowledge, wisdom, workflow, and patient outcomes.", "children": [{"id": "acb6903b-e104-4cb4-98df-38116e1b30e7", "type": "subtopic", "title": "Nursing informatics scope", "description": "The gist is understanding informatics as nursing knowledge work supported by systems.", "children": [{"id": "2f20450a-0e66-44a0-a7eb-4bb21e2146ee", "type": "concept", "title": "Data, information, knowledge, wisdom"}, {"id": "f40421e3-bac7-4842-a1e7-476abd59da36", "type": "concept", "title": "Nursing judgment and technology-enabled care"}, {"id": "697b9162-9dd7-44fa-9208-4fb32672fbdb", "type": "concept", "title": "Roles: bedside nurse, super user, informatics nurse, analyst, CNIO"}]}, {"id": "aa9a4d43-1755-49f3-bf1b-fd9d2099d128", "type": "subtopic", "title": "Sociotechnical systems", "description": "Healthcare technology works only when people, workflow, policy, and tools fit together.", "children": [{"id": "d167c254-e082-4090-a91f-eb415fb200f2", "type": "concept", "title": "People, process, technology, organization, and environment"}, {"id": "38a5c445-fb0d-485f-943c-993e2c69419e", "type": "concept", "title": "Unintended consequences"}, {"id": "d59444c4-44dd-44da-8133-8919592b19d9", "type": "concept", "title": "Safety, quality, and usability as design goals"}]}, {"id": "542ec025-c886-41fe-b08c-769862803bec", "type": "subtopic", "title": "AACN informatics competencies", "description": "Students connect course learning to professional nursing expectations.", "children": [{"id": "72ba971b-c56c-4811-975b-7a6cb65bca70", "type": "concept", "title": "Healthcare technologies"}, {"id": "a5ad3156-1e16-48cf-bca3-fb4267aa79aa", "type": "concept", "title": "Information and communication technologies"}, {"id": "6c8d6656-f1d9-4b57-aff0-2da4add81dd7", "type": "concept", "title": "Data-driven care and ethical practice"}]}]}, {"id": "f720730f-f429-4d92-bd6f-d19372c2bfc1", "type": "topic", "title": "Health Information Systems, EHRs, and Clinical Documentation", "description": "This topic develops fluent, safety-minded use of EHRs and documentation systems as clinical tools rather than passive charting software.", "children": [{"id": "859b2d85-9870-499b-84f5-6720ecaa8a9d", "type": "subtopic", "title": "EHR and EMR foundations", "description": "Students learn what clinical systems store, display, and coordinate.", "children": [{"id": "d0d44128-ed8e-4791-b0c8-d67a00fda2d3", "type": "concept", "title": "Orders, notes, medication administration, results, care plans"}, {"id": "936d1ab9-92f0-4f0f-a4b3-6c440b79a7bb", "type": "concept", "title": "Clinical documentation workflows"}, {"id": "5ed5cedb-e688-4f09-a696-4baa254068e1", "type": "concept", "title": "Chart review and longitudinal patient story"}]}, {"id": "771ea37a-3775-4718-9201-72d97aa31f47", "type": "subtopic", "title": "Clinical documentation quality", "description": "Documentation is clinical communication and legal evidence.", "children": [{"id": "c1a96c9e-41f8-4d55-b211-5795a932309d", "type": "concept", "title": "Accuracy, timeliness, completeness, and relevance"}, {"id": "c3163280-3504-4b6e-8337-cef019237352", "type": "concept", "title": "Problem lists, allergies, medication reconciliation, and handoff notes"}, {"id": "a9f7c090-b89a-47a9-b411-da21cb24e465", "type": "concept", "title": "Copy-forward risks and note bloat"}]}, {"id": "086edf82-955c-4c24-a364-210cb60f779f", "type": "subtopic", "title": "Specialized systems", "description": "Nurses work across many connected platforms.", "children": [{"id": "46bb81cc-91ac-4174-91e9-e52bf0fc87cc", "type": "concept", "title": "CPOE, eMAR, BCMA, LIS, PACS, pharmacy, bed management"}, {"id": "695fabff-f0ba-4fba-aa09-56469951b051", "type": "concept", "title": "Patient portals and scheduling systems"}, {"id": "bc4339c0-27fd-4d43-a3fc-28dca2ee8028", "type": "concept", "title": "Downtime procedures and contingency charting"}]}]}, {"id": "e4b76e7a-8f58-440f-8a89-89491455a52d", "type": "topic", "title": "Standardized Terminologies, Nursing-Sensitive Data, and Data Quality", "description": "Students learn why structured language and high-quality data matter for communication, reimbursement, analytics, quality, and nursing visibility.", "children": [{"id": "8722d243-ec29-4580-ae45-2f00c97897c8", "type": "subtopic", "title": "Nursing terminologies", "description": "Standardized language helps nursing care become visible and computable.", "children": [{"id": "e3715ea2-68a7-4e45-a9b5-fae10ded2bb6", "type": "concept", "title": "NANDA-I diagnoses"}, {"id": "68b87751-db6a-4492-a528-75a40956a926", "type": "concept", "title": "NIC interventions"}, {"id": "7567f9d5-6884-4e49-bfa8-de4eefba31a2", "type": "concept", "title": "NOC outcomes"}, {"id": "02221e3c-b981-4be4-896e-afef4b1f13f9", "type": "concept", "title": "SNOMED CT and LOINC awareness"}]}, {"id": "17dd499f-b9d3-4e17-94e8-68979cc885c7", "type": "subtopic", "title": "Nursing-sensitive data", "description": "Students learn which data reveal nursing contribution to outcomes.", "children": [{"id": "f0d62587-598a-4fe5-8842-810136ada74f", "type": "concept", "title": "Falls, pressure injuries, CAUTI, CLABSI, pain, mobility, education"}, {"id": "fb745dfe-760b-48b9-a754-bf5f10041352", "type": "concept", "title": "Care plans and outcome measures"}, {"id": "76121c5e-ab23-45bb-ba2c-ac4ab6b9e1e6", "type": "concept", "title": "Quality reporting and reimbursement links"}]}, {"id": "d5b480f7-3b7f-4512-8436-926b12d33d09", "type": "subtopic", "title": "Data quality", "description": "Analytics and decision support are only as trustworthy as the underlying data.", "children": [{"id": "73d92ca0-c320-4b8a-81fd-a81095b15693", "type": "concept", "title": "Completeness, validity, consistency, timeliness, and provenance"}, {"id": "8dfcc8f5-2992-49b1-9826-8a2dc99fa405", "type": "concept", "title": "Structured versus unstructured data"}, {"id": "79865fc7-25a9-4f71-9ebd-6da2ede80451", "type": "concept", "title": "Data entry burden and garbage-in/garbage-out"}]}]}, {"id": "ff4cf52d-f019-4bf2-9254-dd5ff44abd21", "type": "topic", "title": "Interoperability, Health Information Exchange, and Data Standards", "description": "This topic explains how health information moves across settings, organizations, systems, and patients using standards and governance.", "children": [{"id": "e3aec2ef-66b9-4e54-b937-7180c2101075", "type": "subtopic", "title": "Interoperability levels", "description": "Students learn the difference between moving data and making data meaningful.", "children": [{"id": "5dab0f48-f36e-4da1-b63f-cd8988853889", "type": "concept", "title": "Technical, semantic, process, and organizational interoperability"}, {"id": "2dab0695-f675-432d-99fa-f2a4d75382b6", "type": "concept", "title": "Care transitions and reconciliation"}, {"id": "86fd17fa-fa67-469a-ac0c-d60477ad36f2", "type": "concept", "title": "Information blocking and patient access concepts"}]}, {"id": "4d625e96-4fbb-4c9c-b606-1e3c768f7175", "type": "subtopic", "title": "Standards landscape", "description": "The point is standards literacy, not programmer-level implementation.", "children": [{"id": "dc1d87b7-50e9-428e-a36d-bee57749976a", "type": "concept", "title": "HL7 v2, C-CDA, FHIR, APIs"}, {"id": "4c46c5bd-ebe1-4868-a197-174f132f7a77", "type": "concept", "title": "USCDI data classes and elements"}, {"id": "60e8e259-d9d9-4fb2-a555-f16313164b13", "type": "concept", "title": "Terminologies: SNOMED CT, LOINC, RxNorm, ICD-10-CM"}]}, {"id": "55de056f-25e3-4f57-80a9-46c7cb257b5d", "type": "subtopic", "title": "Health information exchange", "description": "Students connect data exchange to continuity and safety.", "children": [{"id": "b990202e-3d06-4a83-90ae-69772aa93df7", "type": "concept", "title": "HIE models and query-based exchange"}, {"id": "c9554f24-21d4-471a-a72e-5b7f8bba9cdc", "type": "concept", "title": "Patient matching and identity"}, {"id": "560f5857-8ff6-40d1-8286-0a3c38937f63", "type": "concept", "title": "Transitions of care, referrals, and public health reporting"}]}]}, {"id": "efd79e02-c745-4d2b-8c14-a72eab7065e5", "type": "topic", "title": "Clinical Decision Support, Alert Design, and Medication Safety", "description": "Students learn how digital tools can support judgment while also creating alert fatigue, automation bias, and workflow risk.", "children": [{"id": "782fc2ff-a5e8-4973-9c01-8d3e1b907a35", "type": "subtopic", "title": "Clinical decision support types", "description": "CDS ranges from simple reminders to predictive tools.", "children": [{"id": "ab191ff7-67b7-4b38-af22-73116927271f", "type": "concept", "title": "Order sets, alerts, reminders, templates, calculators"}, {"id": "aa783354-4946-4014-9b06-bc8eeffd6ac9", "type": "concept", "title": "Rules-based versus predictive CDS"}, {"id": "671221b4-a7f2-4412-af2c-6303baa9ccca", "type": "concept", "title": "Knowledge sources and governance"}]}, {"id": "e0858296-0e9d-4762-8562-a6f9c7b1ce18", "type": "subtopic", "title": "Alert design and fatigue", "description": "Bad CDS can train clinicians to ignore important warnings.", "children": [{"id": "953bcebc-32b1-488d-8160-85c139e500c1", "type": "concept", "title": "Specificity, sensitivity, timing, and severity"}, {"id": "2b8e48f9-2f15-4f4c-990a-06890ac8c5ef", "type": "concept", "title": "Interruptive versus passive alerts"}, {"id": "931988f7-9987-4a45-a191-8a96ecfb028e", "type": "concept", "title": "Override reasons and monitoring"}]}, {"id": "1fee0b70-4da7-4db8-be4d-1e93d5974c33", "type": "subtopic", "title": "Medication safety technologies", "description": "Students learn how informatics supports high-reliability medication practice.", "children": [{"id": "7a29dea1-28f7-4d51-9dac-f2c324e4b281", "type": "concept", "title": "CPOE, eMAR, barcode medication administration"}, {"id": "45a703b4-eb83-4ac9-a1e9-9538d55ed6aa", "type": "concept", "title": "Smart pumps and dose-range checking"}, {"id": "a8be01a1-581c-498d-a7f1-adf358a3382d", "type": "concept", "title": "Medication reconciliation and adverse drug event surveillance"}]}]}, {"id": "813de57d-17bf-4ccd-9e37-cf111179ec90", "type": "topic", "title": "Privacy, HIPAA, Cybersecurity, and Ethical Data Stewardship", "description": "This module teaches nurses to protect electronic health information, recognize security risks, and practice ethically in digital environments.", "children": [{"id": "832637b1-7957-4752-a416-5090c5a4b16e", "type": "subtopic", "title": "HIPAA and ePHI", "description": "Students learn core privacy and security obligations for electronic health information.", "children": [{"id": "290938aa-b74c-470e-bcac-7308972706b4", "type": "concept", "title": "Minimum necessary use"}, {"id": "01c8b883-7d72-4568-9142-521216b134b7", "type": "concept", "title": "Access, use, disclosure, and audit trails"}, {"id": "74bb0235-e580-44b2-b076-45c5bc4255c8", "type": "concept", "title": "Covered entities, business associates, and breach basics"}]}, {"id": "4ab127fb-3cb6-4eca-bcd5-22d379ddba33", "type": "subtopic", "title": "Cybersecurity basics", "description": "Nurses are part of the security boundary.", "children": [{"id": "f799045e-0b56-401c-b082-9b5f44806981", "type": "concept", "title": "Phishing, passwords, MFA, ransomware, device security"}, {"id": "26d7a91e-a5cf-4ca0-a4b7-19147b16c3bd", "type": "concept", "title": "Administrative, physical, and technical safeguards"}, {"id": "7f7a72ee-a198-4abc-92bb-951f390bf79f", "type": "concept", "title": "Downtime and cyber incident response"}]}, {"id": "f7236dc4-3b85-4c10-ad48-dcb9e7ffa825", "type": "subtopic", "title": "Ethical stewardship", "description": "Trust is central to digital care.", "children": [{"id": "1af7194a-e5ea-4cc1-b1de-e61dd02c7312", "type": "concept", "title": "Confidentiality and professional boundaries"}, {"id": "a4f9bbc9-aa45-4960-8cf8-0cb65d43f0ca", "type": "concept", "title": "Patient consent and secondary data use"}, {"id": "3503b9e9-df3d-4563-94ee-5fa69c1a9e94", "type": "concept", "title": "Equity, transparency, and accountability"}]}]}, {"id": "1aeaea04-8188-4c1a-89b6-5633c41e6d1a", "type": "topic", "title": "Telehealth, Remote Patient Monitoring, and Digital Therapeutics", "description": "Students learn how virtual care and remote monitoring change assessment, access, patient education, escalation, and continuity of care.", "children": [{"id": "67a1a4e0-773d-4182-9447-f6de0bacfaa4", "type": "subtopic", "title": "Telehealth models", "description": "Students learn how virtual care changes access and assessment.", "children": [{"id": "07ab706b-1099-49b9-ba6e-ec4613293ca2", "type": "concept", "title": "Synchronous, asynchronous, store-and-forward, and hybrid care"}, {"id": "eef2ccbf-a896-4335-bdc3-7e81883e3f1c", "type": "concept", "title": "Teletriage and virtual nursing"}, {"id": "877a9b25-9f7b-4def-812d-7e6cf28216a3", "type": "concept", "title": "Licensure, consent, and emergency planning awareness"}]}, {"id": "d46e7cdf-11ce-473f-8c6f-26d7393f4cc7", "type": "subtopic", "title": "Remote patient monitoring", "description": "RPM turns home data into clinical action.", "children": [{"id": "0802c28e-ada4-4234-ac37-b79e0565a864", "type": "concept", "title": "Vital signs, glucose, weight, oxygen saturation, blood pressure"}, {"id": "991c7088-4057-4494-9fbe-4fb8695f381c", "type": "concept", "title": "Escalation thresholds and monitoring workflows"}, {"id": "62121446-b5e2-4ab8-885b-082fce905d30", "type": "concept", "title": "Device setup, adherence, and data overload"}]}, {"id": "54d48808-1b5d-410c-a88d-9a96e8103505", "type": "subtopic", "title": "Digital therapeutics", "description": "Students evaluate software-enabled interventions as care tools.", "children": [{"id": "3f1403ba-575b-45aa-b31f-e27dd2c4e9a0", "type": "concept", "title": "Evidence, indications, and patient selection"}, {"id": "9cd19715-f628-44aa-93c6-b6894b8ba34b", "type": "concept", "title": "Integration with care plans"}, {"id": "29dd7471-f83a-429d-87d0-c15bf4a01753", "type": "concept", "title": "Safety monitoring and outcome tracking"}]}]}, {"id": "c62b1556-f3e7-430d-a411-e6bdba2de05e", "type": "topic", "title": "Mobile Health, Patient Portals, Wearables, and Patient Engagement", "description": "This topic examines patient-facing technologies and how nurses can support usability, health literacy, equity, and shared decision making.", "children": [{"id": "9b4fac66-0db9-478f-8645-0632fd4aca75", "type": "subtopic", "title": "Patient-facing apps", "description": "Students learn to evaluate health apps beyond convenience.", "children": [{"id": "7a6e7856-e7dd-4fad-9fbb-a3cde60eb866", "type": "concept", "title": "Credibility, privacy, evidence, usability, and accessibility"}, {"id": "2d973b7c-ef63-41c1-81c4-5180b96162a1", "type": "concept", "title": "Medication, symptom, chronic disease, and wellness apps"}, {"id": "f9cec280-2cd0-478a-8d3d-93afa1075bd8", "type": "concept", "title": "App recommendation boundaries"}]}, {"id": "3a45d087-8e57-41bc-a938-94a707d8cece", "type": "subtopic", "title": "Patient portals", "description": "Portals can support access, communication, and self-management.", "children": [{"id": "35889f40-9176-4c41-a79e-4c64369e9eac", "type": "concept", "title": "Results release, secure messaging, appointment scheduling"}, {"id": "3621b733-a0cb-45fc-b9ed-96f048328ffa", "type": "concept", "title": "Open notes and patient understanding"}, {"id": "b63de1a6-d74f-4da0-a9ad-0e81f5612978", "type": "concept", "title": "Portal adoption and support"}]}, {"id": "58732fd7-b3c1-4a24-8b9b-6c243dd0806d", "type": "subtopic", "title": "Wearables and consumer data", "description": "Consumer-generated data can help or mislead care decisions.", "children": [{"id": "194d28f5-b618-4d91-9638-64f3c8d9c944", "type": "concept", "title": "Fitness trackers, ECG wearables, sleep and activity data"}, {"id": "78f8ce8b-2772-4719-a11a-cf42b6c8ed99", "type": "concept", "title": "Signal versus noise"}, {"id": "8a347caa-2de1-4218-9523-e459535d4864", "type": "concept", "title": "Documentation and clinical responsibility"}]}]}, {"id": "865b957d-194f-4e8d-a060-d873e56e4d3d", "type": "topic", "title": "Health Data Analytics, Dashboards, and Quality Improvement", "description": "Students learn to use dashboards and data displays to identify patterns, monitor outcomes, and drive quality improvement.", "children": [{"id": "400f53da-0477-4c5d-8558-29708e78f06f", "type": "subtopic", "title": "Analytics foundations", "description": "Students learn how clinical data become measures.", "children": [{"id": "c4759d70-479f-476b-b254-4e027da95b65", "type": "concept", "title": "Descriptive, diagnostic, predictive, and prescriptive analytics"}, {"id": "67c18c9e-ac0f-4916-9e2a-a6978e1a3613", "type": "concept", "title": "Cohorts, denominators, numerators, and risk adjustment"}, {"id": "58d7ef69-1ba1-4846-b4b7-6bf8a54ec874", "type": "concept", "title": "Run charts and basic trend interpretation"}]}, {"id": "13f79ab2-c95f-43a0-b86b-be6248306dfb", "type": "subtopic", "title": "Dashboards", "description": "Dashboards should support action, not decoration.", "children": [{"id": "fcce1e29-0130-48b0-acec-a36fc3b20cf1", "type": "concept", "title": "Quality, safety, staffing, throughput, and outcome dashboards"}, {"id": "24307ea0-ff03-4acf-933d-5b7369710c2e", "type": "concept", "title": "Drilldowns, thresholds, and visual clarity"}, {"id": "2418ffc1-283e-4346-8316-ce0d1069be13", "type": "concept", "title": "Data latency and measure definitions"}]}, {"id": "65845dd7-0bb8-497e-83c9-cc69dd81c43a", "type": "subtopic", "title": "Quality improvement with data", "description": "Students connect informatics to better care.", "children": [{"id": "6a19c80e-d85f-4598-be2b-0d094616fdce", "type": "concept", "title": "PDSA cycles"}, {"id": "d180f504-5c7f-49bf-b289-d02f0eb12ba9", "type": "concept", "title": "Clinical variation and process measures"}, {"id": "025b1f3d-9c03-4099-8128-a095c8dd78a1", "type": "concept", "title": "Outcome monitoring and sustainment"}]}]}, {"id": "6facbccd-b5f4-44d0-be2a-b82e310eda3b", "type": "topic", "title": "Workflow Design, Human Factors, Usability, and Safety", "description": "This topic teaches students to evaluate whether technology fits clinical work, reduces burden, and supports safe human performance.", "children": [{"id": "297a4757-0009-4d3d-948f-6b43ea732133", "type": "subtopic", "title": "Workflow analysis", "description": "Technology must be designed around real clinical work.", "children": [{"id": "a6d9709b-0c9a-4d9b-9119-2a0b0f1db0bd", "type": "concept", "title": "Current-state and future-state workflow maps"}, {"id": "41763fca-2563-4e77-ae79-64cc82a53892", "type": "concept", "title": "Handoffs, interruptions, queues, and workarounds"}, {"id": "1a6f4aa5-0727-48e3-9cdf-2e45525b7a93", "type": "concept", "title": "Shadowing and stakeholder interviews"}]}, {"id": "4698b6cc-d610-4e74-82d4-06c4a78272ba", "type": "subtopic", "title": "Human factors", "description": "Students learn how systems shape attention, memory, and error.", "children": [{"id": "44c67012-4649-4f19-a160-f4fdf316a870", "type": "concept", "title": "Cognitive load and alarm burden"}, {"id": "61bfa6d6-ad3d-496e-9b22-dd2399cd5066", "type": "concept", "title": "Standardization and forcing functions"}, {"id": "f848b68a-69cf-4e09-b141-c66fae127538", "type": "concept", "title": "Interface design and usability heuristics"}]}, {"id": "5e29e01b-2806-4df0-94be-69b9028c61e2", "type": "subtopic", "title": "Safety evaluation", "description": "Good technology is monitored after go-live.", "children": [{"id": "5e47b521-bed4-494e-9d01-6e55aca2b7e1", "type": "concept", "title": "Usability testing"}, {"id": "f5cf7361-2787-4675-aeef-113b7d44ae40", "type": "concept", "title": "Hazard analysis and safety cases"}, {"id": "5ca84e18-754a-4d89-96bf-005b656859cb", "type": "concept", "title": "Incident reporting and learning systems"}]}]}, {"id": "d091ff16-d13b-4a74-8d4b-ac36ad3b3a20", "type": "topic", "title": "Public Health Informatics, Surveillance, and Population Health", "description": "Students connect clinical data to public health reporting, surveillance, community health, and population-level decision making.", "children": [{"id": "0a4ae6be-fa46-4e39-9f24-94bbc47b60cb", "type": "subtopic", "title": "Public health data systems", "description": "Clinical data supports community-level action when governed and interpreted well.", "children": [{"id": "9a9d8ca2-2c54-497c-8739-649b44d168fa", "type": "concept", "title": "Registries, immunization systems, electronic case reporting"}, {"id": "56a31f7b-1e9c-4942-9161-954566b5d886", "type": "concept", "title": "CDC and public health data sources"}, {"id": "28b631b3-28b7-4694-a310-214c9c48a494", "type": "concept", "title": "Data modernization and surveillance"}]}, {"id": "e998f1c3-7980-4edd-8ce0-f244f8896f5b", "type": "subtopic", "title": "Population health analytics", "description": "Students learn to see patterns beyond individual encounters.", "children": [{"id": "537f2d46-477d-4db0-a8ee-9bae2bc6275f", "type": "concept", "title": "Risk stratification"}, {"id": "4a9b6328-7b9d-4fc2-813b-a01d0ba51243", "type": "concept", "title": "Social determinants of health"}, {"id": "c301f7f7-c43e-4d05-93c6-dc1d41f4e56f", "type": "concept", "title": "Care gaps and outreach lists"}]}, {"id": "3e38ebc2-dae1-4353-948e-18c4dfe76ddc", "type": "subtopic", "